import{z as d,x as A,o,c as B,q as E,j as l,D as i,d as e,s as n,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const M=JSON.parse('{"title":"MSD 同步误差","description":"","frontmatter":{"title":"MSD 同步误差","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/msd-moving-standard-deviation.md","filePath":"litho/msd-moving-standard-deviation.md","lastUpdated":1791413859000}'),p={name:"litho/msd-moving-standard-deviation.md"};function h(D,a,S,m,f,F){const r=A("Mermaid");return o(),B("div",null,[a[2]||(a[2]=E('<h1 id="msd-同步误差" tabindex="-1">MSD 同步误差 <a class="header-anchor" href="#msd-同步误差" aria-label="Permalink to &quot;MSD 同步误差&quot;">​</a></h1><div class="epigraph"><p>扫描要求掩模台与工件台按倍率同步。MSD 是相对位置误差的运动标准差：它糊边，像一架振动的狭缝。</p><footer>—— 对照 moving standard deviation 同步误差；[狭缝扫描平均](/litho/slit-scan-average)</footer></div><p><a href="/litho/stage-acceleration-throughput">上一课</a>把加速写进产能。缺口是匀速扫描段两台是否锁住。本课钉 MSD，不重写套刻向量。先把量级钉住：套刻预算留给同步误差的份额通常只有几纳米，而这要求掩模台按 4 倍速度跑完全场仍然守住——晶圆面几纳米，掩模面就是几十纳米。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>投影倍率把掩模运动与晶圆运动绑在一起。相对误差随时间变，积分到像上是沿扫描向的模糊，NILS 掉、LER 升。编码器各报各的「很准」，相对不准一样废。</p><p>展开：狭缝驻留是毫秒量级，MSD 在这个长度的滑窗上取标准差，等于给相对误差做了一次带通——比窗慢的漂移被平均掉，进套刻账；比窗快的抖动留在窗内，变成模糊。MSD 挑中的频段恰好在伺服最容易漏的地方。后果分两路：密集图形沿扫描向对比下降、<a href="/litho/nils-ils">NILS</a> 掉、剂量裕度变窄；辅助特征本来就弱，模糊后 <a href="/litho/sraf-assist">SRAF</a> 印刷阈值漂，CDU 沿扫描向先坏。单台编码器再准也没用——「相对」误差只有在两把尺互相参照时才可见。</p><p><span class="marginnote">术语翻译：MSD（moving standard deviation，滑动标准差）就是在扫描曝光的几十毫秒里，对「掩模台与工件台的相对位置误差」算一个移动的标准差。这个数越大，扫描瞬间两台越不同步，印出来的边越糊——它把抽象的「同步不好」变成一个可考核的纳米数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>伺服用相对误差作被控量。指标 MSD（moving standard deviation）在扫描窗上算。降 MSD：更硬的控制、更低加速度残振、更好的位置计量。与剂量扫描平均不同：剂量平均强度，MSD 平均的是位置噪声。</p><p>工程抓手按频段排：低频靠 4:1 速度前馈的配比精度，高频靠编码器栅尺质量与安装、气浮或磁浮刚度，基础隔振把地面与真空泵的振动挡在外面（<a href="/litho/vibration-isolation">振动隔离</a>）；加速段的残振必须在进入匀速段前收敛——那是上一课的账，但收敛不好会漏进 MSD。计量侧不靠机械感觉：套刻监测片上的光栅标记在扫描中分两次采样狭缝不同时刻的像，衍射式套刻读出（<a href="/litho/yieldstar-dbo">DBO</a>）给出位移分布的宽度，就是可量产读数的 MSD。指标进 <a href="/litho/overlay-budget">套刻预算</a>与 CDU 周报，按方向分别记账——扫描向与非扫描向的灵敏度不同。</p><p><span class="marginnote">数字实例：4 倍缩小投影下，掩模台要按晶圆台 4 倍的速度反向扫描。晶圆面 2 纳米的同步预算，折到掩模面就是 8 纳米——一台以每秒几百毫米移动的台，要在毫秒级狭缝驻留内把这个数一直守住。</span></p>',11)),(o(),l(s,null,{default:i(()=>[n(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RT%5B%22%E6%8E%A9%E6%A8%A1%E5%8F%B0%22%5D%20--%3E%20REL%5B%22%E7%9B%B8%E5%AF%B9%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20WF%5B%22%E5%B7%A5%E4%BB%B6%E5%8F%B0%22%5D%20--%3E%20REL%0A%20%20REL%20--%3E%20MSD%5B%22%E6%89%AB%E6%8F%8F%E7%AA%97%20MSD%22%5D%0A%20%20MSD%20--%3E%20BLUR%5B%22%E6%89%AB%E6%8F%8F%E5%90%91%E6%A8%A1%E7%B3%8A%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,[t("span",{class:"marginnote"},"High-NA 半场拼接对同步更苛刻：两场接缝处 MSD 会变成可见错位。见 High-NA 课，本课只钉指标。")],-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"像面位移 \\(\\approx\\) 相对台误差 / 倍率关系。时间上的抖动被狭缝驻留时间卷积，等效低通模糊。高频抖更伤边缘。",-1)),a[6]||(a[6]=t("p",null,[e("把这句话写全：曝光期间像面上每一点接收的是狭缝扫过期间误差分布的加权积分，空中像沿扫描向与误差核卷积，核的宽度就是模糊量，MSD 是它的一阶代理。频域看，滑窗平均压制低频、放过与驻留时间相当及更高的频率，所以伺服带宽必须盖住狭缝驻留频段，否则「平均指标正常、边缘照样糊」。步进机没有扫描就没有这个误差通道，振动只表现为整场模糊（"),t("a",{href:"/litho/stepper-vs-scanner"},"步进与扫描"),e("）；掩模一侧还要留意装夹与同步标记的贡献，别把掩模面误差全记到晶圆台头上。")],-1)),(o(),l(s,null,{default:i(()=>[n(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20NOISE%5B%22%E7%9B%B8%E5%AF%B9%E8%AF%AF%E5%B7%AE%E9%9A%8F%E6%97%B6%E9%97%B4%E5%8F%98%22%5D%20--%3E%20WIN%5B%22%E6%AF%AB%E7%A7%92%E7%BA%A7%E6%BB%91%E7%AA%97%20%E5%B9%B3%E5%9D%87%22%5D%0A%20%20WIN%20--%3E%20SLOW%5B%22%E6%85%A2%E4%BA%8E%E7%AA%97%E5%8F%A3%E7%9A%84%E6%BC%82%E7%A7%BB%22%5D%0A%20%20WIN%20--%3E%20FAST%5B%22%E5%BF%AB%E4%BA%8E%E7%AA%97%E5%8F%A3%E7%9A%84%E6%8A%96%E5%8A%A8%22%5D%0A%20%20SLOW%20--%3E%20OV%5B%22%E8%BF%9B%E5%A5%97%E5%88%BB%E6%A8%A1%E5%9E%8B%20%2F%20%E5%AF%B9%E5%87%86%E8%B4%A6%22%5D%0A%20%20FAST%20--%3E%20BLUR%5B%22%E7%95%99%E5%9C%A8%E7%AA%97%E5%86%85%20%E6%88%90%E6%89%AB%E6%8F%8F%E5%90%91%E6%A8%A1%E7%B3%8A%22%5D%0A%20%20BLUR%20--%3E%20NILS%5B%22NILS%20%E6%8E%89%20%2F%20SRAF%20%E9%98%88%E5%80%BC%E6%BC%82%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=E('<p><span class="marginnote">常见误区：只看单台编码器指标就断言「台很准」。同步误差是相对量——两把尺各自都准，互相之间照样能错位；这正是套刻监测片要用衍射读出直接量「位移分布宽度」、而不是信单台报告的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课温控：热使尺和空气变，MSD 和干涉仪一起漂。另外 MSD 只计随机分量：均值的同步偏差走套刻模型与对准账，不在这里重复记账。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MSD 是两台相对误差的扫描统计，直接糊边。</li><li>单台精度好不等于同步好，相对误差要互参才能见。</li><li>滑窗把它做成带通：慢漂移进套刻账，快抖动留在本课。</li><li>出处：狭缝课；扫描同步通识。</li></ul>',5))])}const g=d(p,[["render",h]]);export{M as __pageData,g as default};
